   273  PHP_FUNCTION(realpath)
   274  {
   275          char *filename;
   276          size_t filename_len;
   277          char resolved_path_buff[MAXPATHLEN];
   278
   279          ZEND_PARSE_PARAMETERS_START(1, 1)
   280                  Z_PARAM_PATH(filename, filename_len)
   281          ZEND_PARSE_PARAMETERS_END();
